    <script>
        (() => {
            let stream = null;
            let timer = null;
            let facingMode = 'environment';
            const panel = () => document.getElementById('qrScannerPanel');
            const video = () => document.getElementById('qrVideo');
            const status = (text) => { const el = document.getElementById('qrCameraStatus'); if (el) el.textContent = text; };
            const stop = (hide = true) => { if (timer) { clearInterval(timer); timer = null; } if (stream) { stream.getTracks().forEach(track => track.stop()); stream = null; } const v = video(); if (v) v.srcObject = null; const p = panel(); if (hide && p) p.classList.remove('is-visible'); };
            const cameraLabel = () => facingMode === 'environment' ? 'kamera belakang' : 'kamera depan';
            const setLot = (value) => { const input = document.getElementById('noLot'); if (!input) return; input.value = value; input.dispatchEvent(new Event('input', {bubbles:true})); status('QR terbaca: '+value); setTimeout(() => stop(true), 450); };
            const start = async () => {
                const p = panel(); const v = video();
                if (!p || !v) return;
                if (!window.isSecureContext && location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') { p.classList.add('is-visible'); status('Kamera memerlukan HTTPS atau localhost.'); return; }
                if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { p.classList.add('is-visible'); status('Browser tidak mendukung akses kamera.'); return; }
                try {
                    try {
                        stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:facingMode}}, audio:false});
                    } catch (exactError) {
                        stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facingMode}}, audio:false});
                    }
                    v.srcObject = stream; await v.play(); p.classList.add('is-visible'); status('Arahkan QR ke '+cameraLabel()+'.');
                    if (!('BarcodeDetector' in window)) { status('Browser belum mendukung deteksi QR otomatis. Ketik No Lot secara manual.'); return; }
                    const formats = await BarcodeDetector.getSupportedFormats();
                    if (!formats.includes('qr_code')) { status('Format QR belum didukung browser.'); return; }
                    const detector = new BarcodeDetector({formats:['qr_code']});
                    timer = setInterval(async () => { try { const codes = await detector.detect(v); if (codes.length && codes[0].rawValue) setLot(codes[0].rawValue.trim()); } catch (error) { status('QR belum terbaca, arahkan kamera dengan stabil.'); } }, 250);
                } catch (error) { p.classList.add('is-visible'); status('Akses kamera ditolak atau tidak tersedia. Izinkan kamera pada browser.'); }
            };
            const switchCamera = async () => { if (!stream) return; stop(false); facingMode = facingMode === 'environment' ? 'user' : 'environment'; await start(); };
            document.addEventListener('click', event => { if (event.target.closest('#startQrScan')) start(); if (event.target.closest('#switchQrCamera')) switchCamera(); if (event.target.closest('#stopQrScan')) stop(); });
            document.addEventListener('livewire:navigated', stop);
        })();
    </script>
</div>
